from __future__ import annotations

import csv
import json
from bisect import bisect_left, bisect_right
from collections import defaultdict
from datetime import datetime
from decimal import Decimal


CATALOG_PATH = "/app/dataset/product_catalog.csv"
TEMPERATURE_PATH = "/app/dataset/temperature_logs.csv"
DISPATCH_PATH = "/app/dataset/warehouse_dispatches.csv"


def _parse_ts(value: str) -> datetime:
    return datetime.strptime(value, "%Y-%m-%d %H:%M:%S")


def _load_catalog():
    by_product_id = {}
    by_ean = {}
    max_safe_temp = {}

    with open(CATALOG_PATH, newline="") as f:
        for row in csv.DictReader(f):
            row["unit_price"] = Decimal(row["unit_price"].replace(",", "."))
            row["unit_weight_kg"] = Decimal(row["unit_weight_kg"])
            row["max_safe_temp_c"] = Decimal(row["max_safe_temp_c"])
            by_product_id[row["product_id"]] = row
            by_ean[row["ean_code"]] = row
            max_safe_temp[row["storage_category"].lower()] = row["max_safe_temp_c"]

    return by_product_id, by_ean, max_safe_temp


def _load_temperatures():
    by_zone = defaultdict(list)

    with open(TEMPERATURE_PATH, newline="") as f:
        for row in csv.DictReader(f):
            by_zone[row["zone"].lower()].append(
                (
                    _parse_ts(row["timestamp"]),
                    Decimal(row["temperature_c"].replace(",", ".")),
                )
            )

    index = {}
    for zone, readings in by_zone.items():
        readings.sort()
        index[zone] = {
            "timestamps": [ts for ts, _ in readings],
            "temperatures": [temp for _, temp in readings],
        }
    return index


def _load_dispatches():
    dispatches = []
    by_timestamp = defaultdict(list)

    with open(DISPATCH_PATH, newline="") as f:
        for row in csv.DictReader(f):
            row["dispatch_id"] = int(row["dispatch_id"])
            row["timestamp"] = _parse_ts(row["timestamp"])
            row["quantity"] = int(row["quantity"])
            row["total_weight_kg"] = Decimal(row["total_weight_kg"])
            dispatches.append(row)
            by_timestamp[row["timestamp"]].append(row)

    return dispatches, by_timestamp


def _resolve_product(row, by_product_id, by_ean):
    product = by_product_id.get(row["product_id"])
    if product is None:
        product = by_ean.get(row["product_id"])
    if product is None:
        raise KeyError(f"Unknown product reference in dispatch {row['dispatch_id']}: {row['product_id']}")
    return product


def _zone_breached_around(timestamp: datetime, zone: str, threshold: Decimal, temperatures) -> bool:
    data = temperatures[zone]
    times = data["timestamps"]
    values = data["temperatures"]

    prev_idx = bisect_right(times, timestamp) - 1
    next_idx = bisect_left(times, timestamp)
    if prev_idx < 0 or next_idx >= len(times):
        return False

    return values[prev_idx] > threshold and values[next_idx] > threshold


def _find_confirmed_disposals(dispatches_by_timestamp, by_product_id, by_ean, max_safe_temp, temperatures):
    disposal_ids = set()

    for timestamp, rows in dispatches_by_timestamp.items():
        if len(rows) < 3:
            continue

        categories = set()
        for row in rows:
            product = _resolve_product(row, by_product_id, by_ean)
            categories.add(product["storage_category"].lower())

        if not categories:
            continue

        if not categories <= {"frozen", "meat", "dairy"}:
            continue

        if all(
            _zone_breached_around(timestamp, category, max_safe_temp[category], temperatures)
            for category in categories
        ):
            disposal_ids.update(row["dispatch_id"] for row in rows)

    return disposal_ids


def answer() -> int:
    by_product_id, by_ean, max_safe_temp = _load_catalog()
    temperatures = _load_temperatures()
    dispatches, dispatches_by_timestamp = _load_dispatches()

    disposal_ids = _find_confirmed_disposals(
        dispatches_by_timestamp, by_product_id, by_ean, max_safe_temp, temperatures
    )

    revenue = Decimal("0")
    for row in dispatches:
        if row["dispatch_id"] in disposal_ids:
            continue
        product = _resolve_product(row, by_product_id, by_ean)
        revenue += product["unit_price"] * row["quantity"]

    return int(revenue)


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
